import{_ as o,o as d,c as a,ag as c}from"./chunks/framework.DnFw42UE.js";const p=JSON.parse('{"title":"Migrating from 0.4","description":"","frontmatter":{},"headers":[],"relativePath":"packages/client/reference/migrating.md","filePath":"packages/client/docs/reference/migrating.md"}'),t={name:"packages/client/reference/migrating.md"};function i(r,e,n,s,l,g){return d(),a("div",null,[...e[0]||(e[0]=[c('<h1 id="migrating-from-0-4" tabindex="-1">Migrating from 0.4 <a class="header-anchor" href="#migrating-from-0-4" aria-label="Permalink to &quot;Migrating from 0.4&quot;">​</a></h1><p><code>find</code>, <code>update</code> and <code>delete</code> take <code>documentId: string</code>. Strapi 5 content routes do not accept a numeric <code>id</code>. Users and uploads still use a numeric <code>id</code>, because those plugins do.</p><ul><li><code>find</code> with no id (the old &quot;find all&quot; call) is removed. Use <code>findFirst</code>.</li><li>Every method returns <code>[error, data, meta]</code> instead of <code>[error, data]</code>. <code>meta.pagination</code> carries <code>total</code> and <code>pageCount</code>. <code>const [err, data] = ...</code> still works; the third element is ignored.</li><li><code>T</code> no longer has to declare <code>id</code>.</li><li><code>ServiceError</code> gained <code>name</code>, <code>details</code> and <code>cause</code>. Strapi&#39;s <code>error</code> body, validation details included, is copied into it.</li><li><code>defaultLocale</code> is required. There is no <code>&quot;en&quot;</code> default.</li><li><code>StrapiClient</code> stays a shorthand for one collection and now takes <code>defaultLocale</code>. It has no <code>files</code>, <code>users()</code>, <code>single()</code>, <code>auth</code>, <code>route()</code> or <code>graphql()</code>. Use <code>new Strapi(...)</code> for those.</li></ul><p>The same notes are in <a href="https://github.com/fbritoferreira/strapi/blob/main/packages/client/MIGRATION.md" target="_blank" rel="noreferrer">MIGRATION.md</a>, which npm and JSR ship with the package.</p>',4)])])}const u=o(t,[["render",i]]);export{p as __pageData,u as default};
